import {
  loadResourceIndex
} from "./packager-tool-db4jm1rz.js";
import {
  TYPECACHE_PACKAGE_INDEX_TYPES
} from "./packager-tool-09p89x5n.js";
import {
  ConnectorsApi,
  createApiClient
} from "./packager-tool-1zpm7wts.js";
import {
  catchError
} from "./packager-tool-79gws1zn.js";

// ../case-tool/src/services/connector-lookup-service.ts
async function lookupTypeCacheEntry(uiPathActivityTypeId, type) {
  const types = typeof type === "string" ? [type] : type;
  let entry;
  let matchedType = types[0];
  for (const candidate of types) {
    const [loadError, entries] = await catchError(loadResourceIndex(candidate));
    if (loadError) {
      if (types.length === 1)
        throw loadError;
      continue;
    }
    const match = entries.find((e) => e.uiPathActivityTypeId === uiPathActivityTypeId);
    if (match) {
      entry = match;
      matchedType = candidate;
      break;
    }
  }
  if (!entry) {
    throw new Error(`No entry found in ${types.join(", ")} with uiPathActivityTypeId: ${uiPathActivityTypeId}`);
  }
  const [parseError, config] = catchError(() => JSON.parse(entry.configuration));
  if (parseError) {
    throw new Error(`Failed to parse configuration for "${entry.displayName}" in ${matchedType}: ${parseError.message}`);
  }
  if (!config.connectorKey) {
    throw new Error(`Configuration for "${entry.displayName}" in ${matchedType} is missing connectorKey`);
  }
  return { entry, config, source: matchedType };
}
async function lookupConnectorDisplayName(packageId) {
  if (typeof packageId !== "number")
    return null;
  for (const indexType of TYPECACHE_PACKAGE_INDEX_TYPES) {
    const [err, packages] = await catchError(loadResourceIndex(indexType));
    if (err)
      continue;
    const pkg = packages.find((p) => p.id === packageId);
    if (pkg)
      return pkg.displayName;
  }
  return null;
}
async function fetchConnectorConnections(connectorKey) {
  const [apiError, api] = await catchError(createApiClient(ConnectorsApi));
  if (apiError) {
    throw new Error(`Failed to create Integration Service client: ${apiError.message}`);
  }
  const [fetchError, connections] = await catchError(api.apiV1ConnectorsKeyOrIdConnectionsGet({
    keyOrId: connectorKey,
    allFolders: true,
    folderDefaults: true
  }));
  if (fetchError) {
    throw new Error(`Failed to fetch connections for connector "${connectorKey}": ${fetchError.message}`);
  }
  return connections;
}

export { lookupTypeCacheEntry, lookupConnectorDisplayName, fetchConnectorConnections };

